def find_permutation(n, k):
    p = list(range(1, n + 1))
    distinct_diffs = set()

    for i in range(n - 1):
        distinct_diffs.add(abs(p[i] - p[i + 1]))
        if len(distinct_diffs) == k:
            break

    if len(distinct_diffs) < k:
        return None

    return p

# Read input
n, k = map(int, input().split())

# Find and print the permutation
permutation = find_permutation(n, k)
if permutation:
    print(*permutation)
else:
    print("No solution found")
